module TopModule(
  input  clk,
  input  resetn,
  input  x,
  input  y,
  output reg f,
  output reg g
);
  localparam A = 2'b00;
  localparam B = 2'b01;
  localparam C = 2'b10;
  localparam D = 2'b11;
  reg [1:0] state, next_state;
  reg [2:0] count;
  always @(*) begin
    case (state)
      A: begin
        f = 1;
        g = 0;
        if (!resetn) next_state = A;
        else next_state = B;
      end
      B: begin
        f = 0;
        g = 0;
        if (x == 1 && count == 0) next_state = C;
        else if (x == 0 && count == 1) next_state = D;
        else if (x == 1 && count == 1) next_state = B;
        else next_state = B;
        if (x == 1) count = count + 1;
        else count = 0;
      end
      C: begin
        f = 0;
        g = 1;
        if (y == 1 && count == 0) next_state = C;
        else if (y == 0 && count == 1) next_state = A;
        else if (y == 1 && count == 1) next_state = C;
        else next_state = C;
        if (y == 1) count = count + 1;
        else count = 0;
      end
      D: begin
        f = 0;
        g = 0;
        next_state = A;
      end
    endcase
  end
  always @(posedge clk) state <= next_state;
endmodule

